    has_neg = (d1 < 0) or (d2 < 0) or (d3 < 0)
    has_pos = (d1 > 0) or (d2 > 0) or (d3 > 0)
    return not (has_neg and has_pos)

def point_in_convex_polygon(point, poly):
    n = len(poly)
    if n == 0:
        return False
    if n == 1:
        return point == poly[0]
    if n == 2:
        return point == poly[0] or point == poly[1]

    # For convex polygon, point is inside if it's on same side of all edges
    result = True
    for i in range(n):
        vi = poly[i]
        vj = poly[(i+1)%n]
        cp = cross(vi, vj, point)
        # Check if point is on correct side of each edge
        if cp < 0:
            return False
    return True

