    for i, j in combinations(range(len(points)), 2):
        r1, c1 = points[i]
        r2, c2 = points[j]
        if r1 == r2:
            horiz_seg = (r1, min(c1,c2), max(c1,c2))
            break

    if not horiz_seg:
        return grid

    h_r, h_min, h_max = horiz_seg

    print(f"Horizontal segment found: row {h_r}, cols {h_min} to {h_max}")

    # Fill horizontally within the segment
    for c in range(h_min+1, h_max):
        grid[h_r][c] = 3

    # Now find vertical alignment from other points to this segment
    for p_r, p_c in points:
        if p_r != h_r:
            mid_col = (h_min + h_max) // 2

            # Check if this point is roughly aligned with center
            if abs(p_c - mid_col) <= 2:
                # Fill vertically from this point to the segment
                if p_r < h_r:
                    start_r = p_r + 1
                    end_r = h_r
                else:
                    start_r = h_r + 1
                    end_r = p_r

                for r in range(start_r, end_r):
