    sorted_pts = sorted(points, key=lambda p: (p[0], p[1]))
    print(f"Sorted order: {sorted_pts}")

    # Connect each consecutive pair
    for i in range(len(sorted_pts)-1):
        p1, p2 = sorted_pts[i], sorted_pts[i+1]

        r1, c1 = p1
        r2, c2 = p2

        dy, dx = abs(r2-r1), abs(c2-c1)

        min_r, max_r = min(r1, r2)
        min_c, max_c = min(c1, c2)

        print(f"\nConnecting ({p1}) and ({p2}): dy={dy}, dx={dx}")

        if dy == 0 or dx == 0:
            # Same row or column
            for r in range(min_r, max_r+1):
                for c in range(min_c, max_c):
                    if grid[r][c] == 0:
                        grid[r][c] = 3
        else:
            # Diagonal connection
            g = __import__('math').gcd(dy, dx)
            dr = dy // g
            dc = dx // g

            # Trace diagonal
            cur_r, cur_c = r1 + dr, c1 + dc
