def solve_rule(points):
    """Horizontal segment + dual-column interpolation per row"""
    grid = [[0]*17 for _ in range(15)]

    for r, c in points:
        grid[r][c] = 2

    # Find horizontal segment
    horiz = None
    for i, j in combinations(range(len(points)), 2):
        if points[i][0] == points[j][0]:
            p_i, p_j = points[i], points[j]
            hr, min_c, max_c = p_i[0], min(p_i[1], p_j[1]), max(p_i[1], p_j[1])
            horiz = (hr, min_c, max_c)
            break

    if not horiz:
        return grid

    hr, c_min, c_max = horiz

    for c in range(c_min + 1, c_max):
        grid[hr][c] = 3

    # Each off-segment point contributes TWO columns per affected row
    for pr, pc in points:
        if abs(pr - hr) == 0:
            continue

        if pr < hr:
            start_row, end_row = pr + 1, hr - 1
        else:
            start_row, end_row = hr + 1, pr - 1

        for rr in range(start_row, end_row + 1):
            t = (rr - pr) / abs(hr - pr)

            # Toward c_min
            interp_left = int(round(pc + t * (c_min - pc)))
            # Toward c_max
            interp_right = int(round(pc + t * (c_max - pc)))

            if 0 <= interp_left < 17:
                grid[rr][interp_left] = 3
            if 0 <= interp_right < 17:
                grid[rr][interp_right] = 3

    return grid

