def solve_final(points):
    """Final solution with verified rule"""
    grid = [[0]*17 for _ in range(15)]

    # Place original 2s
    for r, c in points:
        grid[r][c] = 2

    # Find horizontal segment
    horiz = None
    for i, j in combinations(range(len(points)), 2):
        if points[i][0] == points[j][0]:
            p_i, p_j = points[i], points[j]
            hr, min_c, max_c = p_i[0], min(p_i[1], p_j[1]), max(p_i[1], p_j[1])
            horiz = (hr, min_c, max_c)
            break

    if not horiz:
        return grid

    hr, c_min, c_max = horiz

    # Fill horizontal interior
    for c in range(c_min + 1, c_max):
        grid[hr][c] = 3

    # Vertical projection with capped count
    for pr, pc in points:
        if abs(pr - hr) == 0:
            continue

        if pr < hr:
            dist = hr - pr
            num_rows = min(dist - 1, 3)
            end_row = pr + num_rows
            for rr in range(pr + 1, end_row + 1):
                grid[rr][pc] = 3
        else:
            dist = pr - hr
            num_rows = min(dist - 1, 3)
            start_row = hr + 1
            end_row = start_row + num_rows - 1
            for rr in range(start_row, end_row + 1):
                grid[rr][pc] = 3

    return grid

